const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roleLabels={sindaco:'Candidatura a sindaco',consigliere:'Candidato in lista per il consiglio',presidente:'Candidato alla presidenza (Regione o Provincia)',deputato:'Candidato alla Camera',senatore:'Candidato al Senato',uninominale:'Collegio uninominale simulato',eurodeputato:'Candidato al Parlamento europeo'};
// Who can stand in a vote of the calendar, and if not why: the same check the campaign setup and the start of the campaign make (offices held, the rhythm of the candidacies), asked
// once for every role of that kind of vote. Used by the «Candidati» buttons, which take the player straight to the right procedure or say exactly what stands in the way.
export function candidacyAccess(state,entry) {
  const roles=ROLE_OPTIONS[entry.type]??[];
  const held=heldOfficesOf(state);
  const candidacies=personalCandidacies(state.game,state.races?.items??[]);
  const municipalVote=upcomingElections(state.game??{elections:[]}).find(item=>item.type==='comunale')?.electionDate??null;
  const blocks=roles.map(([id,label])=>({id,label,reason:candidacyBlock({held,electionType:entry.type,role:id,electionDate:entry.electionDate,windowOpensAt:entry.windowOpensAt??null,municipalVote,candidacies,candidacyId:entry.id,early:Boolean(entry.early)})}));
  const available=blocks.filter(item=>!item.reason);
  const reasons=[...new Set(blocks.map(item=>item.reason).filter(Boolean))];
  return {ok:available.length>0,roles:blocks,available,reason:available.length?null:(reasons.length?reasons.join(' '):'Per questo voto non c’è un ruolo a cui puoi candidarti.'),partial:available.length>0&&available.length<blocks.length};
}
const ROLE_OPTIONS={comunale:[['sindaco','Sindaco'],['consigliere','Consigliere']],provinciale:[['presidente','Presidente della Provincia'],['consigliere','Consigliere provinciale']],regionale:[['presidente','Presidente di Regione'],['consigliere','Consigliere regionale']],politiche:[['deputato','Deputato (lista)'],['senatore','Senatore (lista)'],['uninominale','Collegio uninominale']],europee:[['eurodeputato','Eurodeputato']]};
const number=value=>new Intl.NumberFormat('it-IT').format(Math.round(Number(value)||0));
// The weight of an area in percent: the decimals a small positive weight needs to not read as 0% (the values themselves are not touched).
const weightPercent=value=>{const weight=Number(value)||0;if(weight>0&&weight<1)return new Intl.NumberFormat('it-IT',{maximumSignificantDigits:2}).format(weight);return number(weight);};
const pct=value=>`${Number(value??0).toLocaleString('it-IT',{maximumFractionDigits:1})}%`;
const partyName=party=>party?.officialName??party?.name??'Indipendente';
const partyDescription=party=>party?.source==='real'?party.factualDescription:party?.description;
// Documented people show only verified identity data; their campaign numbers remain simulated.
const realIdentity=candidate=>candidate?.realReference?`Deputato in carica${candidate.realReference.groupName?` · ${candidate.realReference.groupName}`:''}${candidate.realReference.electedOnList?` · eletto nel 2022 nella lista ${candidate.realReference.electedOnList}`:''}`:null;
const realSourceLink=candidate=>candidate?.realReference?.sourceUrl?`<a class="text-link" href="${esc(candidate.realReference.sourceUrl)}" target="_blank" rel="noopener noreferrer">Scheda ufficiale ↗</a>`:'';
const sourceText=source=>source==='real'?'Dato reale verificato':source==='user'?'Creato da te':'Dato simulato';
const COST_NAMES={volunteers:'vol.',organization:'org.',politicalCapital:'cap. politico'};
const activityCost=activity=>Object.entries(activity.cost).filter(([,value])=>value).map(([name,value])=>`${name==='money'?`€${number(value)}`:`${value} ${COST_NAMES[name]??name}`}`).join(' · ')||'Nessun costo diretto';
const CATEGORY_GROUPS=[['territory','Territorio e porta a porta','pin'],['event','Eventi e comizi','megaphone'],['media','Media, social e confronti','media'],['ads','Pubblicità e affissioni','news'],['internal','Partito, lista e alleanze','users'],['resources','Fondi','money']];
const SCOPE_NAMES={internal:'Partito',media:'Media',debate:'Confronto',national:'Tutto il territorio',broad:'Tutto il territorio',focused:'Area scelta',rival:'Contro un avversario',any:'Risorse'};
// A select's choice kept by the page between redraws, while it is still one of the options; otherwise the default.
const picked=(value,ids,fallback)=>value!=null&&ids.includes(value)?value:fallback;
const factorLabel=value=>value>=1.05?`×${String(Math.round(value*100)/100).replace('.',',')}`:value<=.95?`×${String(Math.round(value*100)/100).replace('.',',')}`:'';

export function renderCampaignPage(state,parties=[],logoFor=()=>null,picks={}) {
  const campaign=state.campaign;
  if(!state.career?.playerId)return `<div class="campaign-empty"><p class="campaign-kicker">PREPARA UNA SFIDA</p><h2>Prima crea il tuo politico</h2><p>La carriera serve per definire territorio, partito e punto di partenza.</p><button class="primary-button" data-action="new-career">Crea il politico</button></div>`;
  if(!campaign||campaign.status==='finished')return campaign?.status==='finished'?renderResult(campaign,parties,logoFor,state):renderSetup(state,parties,logoFor,picks);
  return renderActive(campaign,parties,logoFor,picks);
}

// The strategies that can be chosen in a stage: those of the runoff only between the two rounds.
const strategiesOf=(stage='campagna')=>Object.entries(CAMPAIGN_STRATEGIES).filter(([id])=>strategyStages(id).includes(stage));
function strategyCards(selected='consolidare',name='campaign-strategy',stage='campagna') {
  return `<div class="campaign-strategies" role="radiogroup" aria-label="Strategia della campagna">${strategiesOf(stage).map(([id,item])=>`<label class="campaign-strategy ${selected===id?'is-selected':''}" data-strategy="${id}"><input type="radio" name="${name}" value="${id}" ${selected===id?'checked':''} data-campaign-strategy-choice /><span class="campaign-strategy-icon">${glyph(item.icon,16)}</span><span><strong>${esc(item.label)}</strong><small>${esc(item.detail)}</small><em class="pros">+ ${esc(item.pros)}</em><em class="cons">− ${esc(item.cons)}</em></span></label>`).join('')}</div>`;
}

// The next vote the player can actually face, in chronological order: the first election still to come (open or not yet open) for which at least one role passes the same checks the start of
// the campaign makes. The votes before it that the player cannot stand in are listed with the reason, so the card never jumps to a later (or a local) vote without saying why. The type picked
// by hand in the form does not enter here: it only changes what the form starts.
export function nextChallenge(state) {
  const today=state.clock?.currentDate??'';
  const chain=upcomingElections(state.game??{elections:[]}).filter(item=>(item.status==='open'||item.status==='upcoming')&&item.electionDate>=today&&ROLE_OPTIONS[item.type]).sort((a,b)=>a.electionDate.localeCompare(b.electionDate)||a.windowOpensAt.localeCompare(b.windowOpensAt));
  const skipped=[];
  for (const entry of chain) {
    const access=candidacyAccess(state,entry);
    if (access.ok) return {next:entry,access,skipped,chain};
    skipped.push({entry,reason:access.reason});
  }
  return {next:null,access:null,skipped,chain};
}
// The size class of the comune is not a choice: it comes from the data of the comune (src/core/municipal-rules.js), and the page says on what.
function bandNote(state) {
  const place=state.dataset.politicians.find(item=>item.id===state.career.playerId);
  const info=bandOfMunicipality(place?.municipalityCode??state.career.municipalityCode??state.game?.place?.municipalityCode??null);
  const text=bandDescription(info);
  return `<div class="municipality-band-field" data-municipality-band="${esc(info.band)}" data-municipality-basis="${esc(info.basis)}"><span class="campaign-kicker">DIMENSIONE DEL COMUNE</span><strong>${esc(text.title)}</strong><small>${esc(text.body)}</small><small>${esc(info.label)}${info.provisional?' · provvisoria':''}${info.nearThreshold?' · vicino alla soglia: con la popolazione legale la fascia potrebbe cambiare':''} · ${esc(info.note)}</small><small class="campaign-legal-ref">Riferimenti: ${esc(MUNICIPAL_LEGAL_REFERENCES.law)}. ${esc(MUNICIPAL_LEGAL_REFERENCES.verification)}.</small></div>`;
}
function renderSetup(state,parties,logoFor,picks={}) {
  const player=state.dataset.politicians.find(item=>item.id===state.career.playerId);
  const party=parties.find(item=>item.id===(player?.partyId??state.career.partyId));
  const logo=party&&logoFor(party)?`<img class="campaign-party-logo" src="${esc(logoFor(party))}" alt="${esc(party.logoAlt??`Logo ${partyName(party)}`)}">`:'';
  const partyCard=party?`<div class="campaign-party-identity">${logo}<div><small>${sourceText(party.source)}</small><strong>${esc(partyName(party))}${party.abbreviation?` · ${esc(party.abbreviation)}`:''}</strong><span>${esc(partyDescription(party)||'La scheda mostra solo le informazioni documentate.')}</span>${party.website?`<a href="${esc(party.website)}" target="_blank" rel="noopener noreferrer">Sito ufficiale ↗</a>`:''}</div><button class="text-link" data-party-profile="${esc(party.id)}">Scheda del partito ↗</button></div>`:`<div class="campaign-party-identity"><div><small>APPARTENENZA</small><strong>Indipendente</strong><span>La campagna parte senza lista di partito.</span></div></div>`;
  const open=state.game?upcomingElections(state.game).filter(item=>item.status==='open'):[];
  const challenge=nextChallenge(state);
  const type=picked(picks['setup.electionType'],Object.keys(ROLE_OPTIONS),challenge.next?.type??open[0]?.type??challenge.chain[0]?.type??'comunale');
  const roles=ROLE_OPTIONS[type]??ROLE_OPTIONS.comunale;
  // The offices held decide which candidacies are possible (a provincial seat needs a seat in a comune; the Government does not run for a territorial office).
  const held=heldOfficesOf(state);
  const electionDate=open.find(item=>item.type===type)?.electionDate??upcomingElections(state.game??{elections:[]}).find(item=>item.type===type)?.electionDate??null;
  const municipalVote=upcomingElections(state.game??{elections:[]}).find(item=>item.type==='comunale')?.electionDate??null;
  const openEntry=open.find(item=>item.type===type)??null;
  const candidacies=personalCandidacies(state.game,state.races?.items??[]);
  const blockOf=id=>candidacyBlock({held,electionType:type,role:id,electionDate,windowOpensAt:openEntry?.windowOpensAt??null,municipalVote,candidacies,candidacyId:openEntry?.id??null,early:Boolean(openEntry?.early)});
  const available=roles.filter(([id])=>!blockOf(id)).map(([id])=>id);
  // The rhythm of the candidacies (one a year, never two campaigns that touch) bars every role of the vote: said once, with the button off.
  const rhythmReason=roles.length&&!available.length&&openEntry?candidacyBlock({held:[],electionType:type,role:roles[0][0],electionDate,windowOpensAt:openEntry.windowOpensAt??null,candidacies,candidacyId:openEntry.id,early:Boolean(openEntry.early)}):null;
  const choice={objective:picked(picks['setup.objective'],Object.keys(CAMPAIGN_OBJECTIVES),'build'),role:picked(picks['setup.role'],available.length?available:roles.map(([id])=>id),(available.length?available:roles.map(([id])=>id))[0]),topicId:picked(picks['setup.topicId'],DEBATE_TOPICS.map(topic=>topic.id),DEBATE_TOPICS[0].id),strategy:picked(picks['setup.strategy'],strategiesOf('campagna').map(([id])=>id),'consolidare')};
  const openList=open.length?`<div class="campaign-open-list">${open.map(item=>`<div class="campaign-open"><strong>${esc(item.label)}</strong><small>Candidature fino al ${esc(formatDate(item.windowClosesAt))} · voto il ${esc(formatDate(item.electionDate))}</small></div>`).join('')}</div>`:'';   // (the card above already says when the window opens)
  // Which vote the choice refers to: the one of the calendar, named with its place (“Regionali · Lombardia”), with its dates; or none yet.
  const target=openEntry??upcomingElections(state.game??{elections:[]}).find(item=>item.type===type)??null;
  const targetLine=target?`<p class="campaign-target" data-campaign-target="${esc(target.id)}"><strong>${esc(target.label)}</strong> · voto il ${esc(formatDate(target.electionDate))} · candidature ${esc(formatDate(target.windowOpensAt))} – ${esc(formatDate(target.windowClosesAt))}${target.early?' · anticipate':''}</p>`:`<p class="campaign-target" data-campaign-target="">Nessun voto di questo tipo in calendario.</p>`;
  // The action to run for office is at the top of the page, with the dates it depends on: voting day, the window of the candidacies, what is open now.
  const daysTo=date=>date?Math.round((Date.parse(`${date}T12:00:00`)-Date.parse(`${state.clock.currentDate}T12:00:00`))/86400000):null;
  const canStart=Boolean(openEntry)&&available.length>0&&!rhythmReason;
  // The card is about ONE vote: the next one the player can face (nextChallenge), with its own dates, countdown and action; the form below may be set on another type without changing it.
  const shown=challenge.next??null;
  const shownOpen=shown?.status==='open';
  const closesIn=shownOpen?daysTo(shown.windowClosesAt):null, opensIn=shown&&!shownOpen?daysTo(shown.windowOpensAt):null;
  const windowChip=!shown?`<span class="cta-chip is-none">${glyph('alert',14)} Nessun voto a cui puoi candidarti in calendario</span>`:shownOpen?`<span class="cta-chip is-open">${glyph('target',14)} Candidature aperte${closesIn!==null?` · chiudono tra ${closesIn} ${closesIn===1?'giorno':'giorni'}`:''}</span>`:`<span class="cta-chip is-wait">${glyph('clock',14)} Candidature tra ${opensIn} ${opensIn===1?'giorno':'giorni'}</span>`;
  const formOnOther=shown&&shown.type!==type;
  const costHint=rhythmReason?rhythmReason:formOnOther?`Il modulo qui sotto è impostato su «${ELECTION_MODELS[type].label}», non su questa sfida: la campagna parte per ciò che scegli nel modulo.`:shownOpen&&canStart?'Scegli ruolo, obiettivo e strategia qui sotto, poi parti: nessun costo per candidarsi, le attività della campagna costano giorni, fondi o capitale.':'La finestra non è ancora aperta: puoi preparare ruolo e strategia e partire quando si apre.';
  // The votes before the next one the player cannot stand in: said with the reason, and the next valid chance is the one the card shows.
  const skippedNote=challenge.skipped.length?`<ul class="cta-skipped" data-cta-skipped>${challenge.skipped.map(item=>`<li>${glyph('alert',13)}<span><b>${esc(item.entry.label)}</b> (${esc(formatDate(item.entry.electionDate))}): non puoi candidarti. ${esc(item.reason)}</span></li>`).join('')}</ul>`:'';
  const emptyNote=!shown?`<p class="cta-none" data-cta-none>${challenge.chain.length?'Nessuna elezione in calendario ammette una tua candidatura ora: ogni voto ha un motivo che lo impedisce (sopra).':'Nessuna elezione in calendario: il calendario reale dei voti si carica con la pagina.'}</p>`:'';
  const ctaDisabled=!shown||rhythmReason;
  const cta=`<section class="campaign-cta ${shownOpen&&!formOnOther?'is-open':'is-closed'}" data-campaign-cta data-challenge="${esc(shown?.id??'')}"><div class="cta-info"><span class="campaign-kicker">${glyph('ballot',14)} LA TUA PROSSIMA SFIDA</span><h2>${esc(shown?.label??'Nessuna sfida disponibile')}</h2><ul class="cta-facts">${shown?`<li>${glyph('ballot',15)}<span>Voto</span><b>${esc(formatDate(shown.electionDate))}</b></li><li>${glyph('clock',15)}<span>Candidature</span><b>${esc(formatDate(shown.windowOpensAt))} – ${esc(formatDate(shown.windowClosesAt))}</b></li>`:''}<li>${windowChip}</li></ul>${skippedNote}${emptyNote}</div><div class="cta-action"><button class="primary-button cta-button" data-action="campaign-start" ${ctaDisabled?'disabled aria-disabled="true"':''}>${shownOpen&&canStart&&!formOnOther?'Candidati e inizia la campagna':formOnOther&&canStart?`Candidati: ${esc(ELECTION_MODELS[type].label)}`:'Prepara la campagna'} →</button><small>${esc(costHint)}</small></div></section>`;
  return `${cta}
  <section class="campaign-setup" id="campaign-setup"><div class="campaign-section-head"><div><span class="campaign-kicker">LA SFIDA</span><h3>Imposta la campagna</h3></div><time>${esc(formatDate(state.clock.currentDate))}</time></div>${openList}${targetLine}${rhythmReason?`<p class="campaign-real-note" role="status"><strong>Candidatura non disponibile.</strong> ${esc(rhythmReason)}</p>`:''}<div class="campaign-setup-grid"><label>Tipo di elezione<select data-campaign-setup="electionType">${Object.keys(ROLE_OPTIONS).map(id=>`<option value="${id}" ${id===type?'selected':''}>${esc(ELECTION_MODELS[id].label)}${open.some(item=>item.type===id)?' · candidature aperte':''}</option>`).join('')}</select></label><label>Obiettivo<select data-campaign-setup="objective">${Object.entries(CAMPAIGN_OBJECTIVES).map(([id,item])=>`<option value="${id}" ${id===choice.objective?'selected':''}>${esc(item.label)}</option>`).join('')}</select></label><label>Ruolo in candidatura<select data-campaign-setup="role">${roles.map(([id,label])=>`<option value="${id}" ${id===choice.role?'selected':''} ${blockOf(id)?'disabled':''}>${esc(label)}${blockOf(id)?' · non disponibile':''}</option>`).join('')}</select></label>${type==='comunale'?bandNote(state):''}<label>Tema (per la strategia sui temi)<select data-campaign-setup="topicId">${DEBATE_TOPICS.map(topic=>`<option value="${topic.id}" ${topic.id===choice.topicId?'selected':''}>${esc(topic.label)}</option>`).join('')}</select></label></div>${[...roles.filter(([id])=>blockOf(id)).map(([id,label])=>`${label}: ${blockOf(id)}`),...candidacyNotes({held,electionType:type,role:choice.role})].map(text=>`<p class="campaign-real-note campaign-office-note">${esc(text)}</p>`).join('')}<p class="campaign-model-help" data-campaign-model-help>${esc(ELECTION_MODELS[type].strategy)} · <a href="${esc(ELECTION_MODELS[type].referenceUrl)}" target="_blank" rel="noopener noreferrer">${esc(ELECTION_MODELS[type].referenceName)} ↗</a></p>
  <div class="campaign-setup-strategy"><span class="campaign-kicker">STRATEGIA ELETTORALE</span><p class="campaign-real-note">La strategia cambia cosa rende di più, quanto rischi e quanto può oscillare il risultato. Si può cambiare durante la campagna, a un costo.</p>${strategyCards(choice.strategy)}</div>
  <div class="campaign-setup-party"><span class="campaign-kicker">PARTITO E CANDIDATURA</span>${partyCard}${party&&party.source!=='user'?`<p class="campaign-real-note">La candidatura in un partito esistente parte come <strong>da negoziare</strong>: superare la soglia di sostegno interno la rende probabile, non certa. Riunioni e costruzione della lista aumentano le probabilità; la ricandidatura parlamentare non è garantita.</p>`:''}</div><div class="campaign-setup-bottom"><div><strong>La tua base:</strong> ${esc(player?.municipality??'')} · ${esc(player?.region??'')}<span> · ${esc(careerLevelLabel(state.career.currentLevel??state.career.initialLevel)??'')}</span></div><button class="primary-button" data-action="campaign-start" ${rhythmReason?'disabled aria-disabled="true"':''}>Inizia la campagna →</button></div></section>
  <details class="campaign-method"><summary>Come funziona ogni elezione</summary><span>Comunale: comune e regole per fascia di popolazione; il ballottaggio c’è solo se nessuno supera la metà dei voti validi.</span><span>Provinciale: elezione di secondo livello, votano sindaci e consiglieri della provincia.</span><span>Regionale: aree della regione e premio al vincitore.</span><span>Politiche: collegi, liste bloccate e soglia del 3%.</span><span>Europee: circoscrizioni, preferenze e soglia del 4%.</span><small class="campaign-note-small">Scenario di gioco: le proiezioni non sono sondaggi né previsioni ufficiali; i dati delle organizzazioni reali restano separati dalle variabili simulate.</small></details>`;
}

function phaseStrip(campaign,summary) {
  const phases=campaign.stage==='ballottaggio'?['ballottaggio']:['apertura','centrale','finale'];
  return `<section class="campaign-phases" aria-label="Fasi della campagna">${phases.map(id=>`<div class="campaign-phase ${summary.phase===id?'is-current':''} ${phases.indexOf(id)<phases.indexOf(summary.phase)?'is-done':''}"><strong>${esc(CAMPAIGN_PHASES[id].label)}</strong><small>${esc(CAMPAIGN_PHASES[id].detail)}</small></div>`).join('')}</section>`;
}
function strategyPanel(campaign,picks={}) {
  const strategy=strategyOf(campaign);
  const fit=strategy.id?strategyFit(campaign,strategy.id):1;
  const target=campaign.candidates.find(item=>item.id===campaign.strategy?.targetId);
  const topic=DEBATE_TOPICS.find(item=>item.id===campaign.strategy?.topicId);
  const rivals=campaign.candidates.filter(item=>!item.isPlayer&&item.status==='active');
  const locked=campaign.totalDays-campaign.day<=5;
  const chosen={strategy:picked(picks.strategy,strategiesOf(campaign.stage).map(([id])=>id),strategyAvailable(campaign,strategy.id)?strategy.id:strategiesOf(campaign.stage)[0][0]),topicId:picked(picks.strategyTopic,DEBATE_TOPICS.map(item=>item.id),campaign.strategy?.topicId??campaign.nationalContext.salientTopic),targetId:picked(picks.strategyTarget,rivals.map(item=>item.id),campaign.strategy?.targetId)};
  return `<section class="campaign-block campaign-strategy-panel"><div class="campaign-section-head"><div><span class="campaign-kicker">STRATEGIA</span><h3>${esc(strategy.label)}${topic?` · ${esc(topic.label)}`:''}${target?` · contro ${esc(target.realReference?.fullName??'una candidatura simulata')}`:''}</h3></div><span class="campaign-fit ${fit>=1.05?'good':fit<=.92?'bad':''}">${fit>=1.05?'Adatta al momento':fit<=.92?'Poco adatta al momento':'Neutra al momento'} · ${String(Math.round(fit*100)/100).replace('.',',')}</span></div>${strategy.id?`<p class="campaign-strategy-copy"><em class="pros">+ ${esc(strategy.pros)}</em><em class="cons">− ${esc(strategy.cons)}</em></p>`:'<p class="campaign-strategy-copy">Nessuna strategia dichiarata: ogni attività rende il suo valore base.</p>'}
    <details class="campaign-strategy-change"><summary>${campaign.runoff?.freeSwitch?'Scegli la strategia dei due turni (la prima scelta è gratuita)':strategy.id?'Cambia strategia (2 capitale politico, un po’ di credibilità)':'Scegli una strategia'}</summary>${strategyCards(chosen.strategy,'campaign-strategy-live',campaign.stage)}<div class="campaign-activity-controls"><label>Tema<select data-campaign-strategy-topic>${DEBATE_TOPICS.map(item=>`<option value="${item.id}" ${item.id===chosen.topicId?'selected':''}>${esc(item.label)}${item.id===campaign.nationalContext.salientTopic?' · al centro del dibattito':''}</option>`).join('')}</select></label><label>Avversario da contrastare<select data-campaign-strategy-target>${rivals.map(item=>`<option value="${esc(item.id)}" ${item.id===chosen.targetId?'selected':''}>${esc(item.realReference?.fullName??item.displayName)}</option>`).join('')}</select></label><button class="secondary-button" data-campaign-strategy-apply ${locked?'disabled':''}>${locked?'Negli ultimi 5 giorni non si cambia':'Applica la strategia'}</button></div></details></section>`;
}

const signed=value=>`${Number(value)>0?'+':''}${String(Math.round(Number(value)*10)/10).replace('.',',')}`;
const nameOf=(campaign,parties,id)=>{const candidate=campaign.candidates.find(item=>item.id===id);if(!candidate)return 'una candidatura';if(candidate.isPlayer)return 'te';const affiliated=parties.find(item=>item.id===candidate.partyId);return candidate.realReference?.fullName??(affiliated?partyName(affiliated):candidate.displayName);};
const MOTIVES={ideale:'condivide le tue proposte',interesse:'cerca un posto o una garanzia',ostilita:'vuole fermare un altro candidato',convenienza:'punta sul vincitore',amicizia:'si fida di te'};
// What the engine produces beyond the numbers: the crew, the turnout, the record of the term, the list, the endorsements, the promises and the runoff.
function depthPanels(campaign,summary,parties) {
  const blocks=[];
  const crew=summary.crew;
  blocks.push(`<section class="campaign-block campaign-crew"><div class="campaign-section-head"><div><span class="campaign-kicker">SQUADRE E VOLONTARI</span><h3>Chi lavora per te</h3></div><small>${crew.tired?'Squadre stanche: una giornata di riposo rende più di un altro giorno di campagna':'La fatica cresce con l’intensità e scende con il riposo; organizzazione e quantità la contengono'}${crew.lost?` · ${crew.lost} volontari persi per stanchezza`:''}</small></div>${crew.teams.map(team=>`<div class="campaign-area-row"><div><strong>${esc(team.label)}</strong><small>${number(team.size)} volontari · qualità ${number(team.quality)} · resa ×${String(team.efficiency).replace('.',',')}</small></div><strong>${number(team.fatigue)}%</strong><div class="campaign-meter"><i style="width:${Math.max(3,team.fatigue)}%"></i></div></div>`).join('')}${summary.turnout?`<p class="campaign-footnote">Affluenza prevista ${pct(summary.turnout.value)} · mobilitazione ${signed(summary.turnout.parts.mobilization)} · clima ${signed(summary.turnout.parts.climate)}${campaign.stage==='ballottaggio'?` · ballottaggio ${signed(summary.turnout.parts.runoff)}`:''}. Organizzazione, volontari ben preparati e mobilitazione al voto spostano l’affluenza e, con essa, i voti.</p>`:''}</section>`);
  const inc=campaign.incumbency;
  const incumbents=campaign.candidates.filter(item=>item.incumbent&&item.status!=='eliminated');
  if(inc||incumbents.length) blocks.push(`<section class="campaign-block campaign-incumbency"><div class="campaign-section-head"><div><span class="campaign-kicker">IL MANDATO</span><h3>${inc?(inc.former?'Il mandato che hai guidato':'Il bilancio del tuo mandato'):'L’amministrazione uscente'}</h3></div>${inc?`<small>giudizio sul mandato ${signed(inc.standing)} · parti con ${signed(inc.start)} punti</small>`:''}</div>${(inc?.notes??[]).map(text=>`<div class="campaign-log-row"><time>·</time><div><strong>${esc(text)}</strong></div></div>`).join('')}${inc?`<p class="campaign-footnote">Impegni rispettati ${number(inc.record.kept)}, disattesi ${number(inc.record.broken)} · bocciature di bilancio ${number(inc.record.failures)} · servizi ${signed(inc.record.servicesDelta)}</p>`:''}${incumbents.map(item=>`<div class="campaign-log-row"><time>·</time><div><strong>${esc(nameOf(campaign,parties,item.id))}: ${esc(item.incumbency.label)}</strong><small>giudizio ${signed(item.incumbency.score)} · vantaggio di partenza ${signed(item.incumbency.boost)}</small></div></div>`).join('')}</section>`);
  const standing=campaign.list?listStanding(campaign):null;
  if(standing) {
    const mates=[...campaign.list.mates].sort((a,b)=>b.strength-a.strength).slice(0,3);
    blocks.push(`<section class="campaign-block campaign-list"><div class="campaign-section-head"><div><span class="campaign-kicker">LA LISTA</span><h3>Con chi sei in lista</h3></div><small>qualità della lista ${number(standing.quality)} (partenza ${number(standing.baseline)}) · posto ${campaign.nomination.status==='approved'?campaign.candidacy.listPosition:campaign.nomination.listPosition}</small></div><div class="campaign-log-row"><time>·</time><div><strong>${standing.ahead===0?'Nessun nome pesa più di te':`${standing.ahead} ${standing.ahead===1?'nome pesa':'nomi pesano'} più di te`}</strong><small>composizione, forza sul territorio, correnti del partito e trattative decidono il posto · scouting ${number(campaign.list.scouted)} · concessioni ${number(campaign.list.concessions)}</small></div></div>${mates.map(item=>`<div class="campaign-log-row"><time>${number(item.strength)}</time><div><strong>${esc(item.label)}${item.scouted?' (scovato da te)':''}</strong><small>${esc(item.faction.replace('-',' '))}${campaign.territories.find(area=>area.id===item.areaId)&&campaign.territories.length>1?` · ${esc(campaign.territories.find(area=>area.id===item.areaId).name)}`:''}</small></div></div>`).join('')}</section>`);
  }
  const given=campaign.endorsements?.given??[];
  const obligations=campaign.obligations??[];
  if(given.length||obligations.length) blocks.push(`<section class="campaign-block campaign-endorsements"><div class="campaign-section-head"><div><span class="campaign-kicker">SOSTEGNI E IMPEGNI</span><h3>Chi ti sostiene, a che prezzo</h3></div><small>${number(campaign.commitments??0)} impegni da mantenere dopo il voto</small></div>${given.slice(-4).reverse().map(item=>`<div class="campaign-log-row"><time>G${item.day}</time><div><strong>${esc(item.label)} · +${String(item.points).replace('.',',')}</strong><small>${esc(MOTIVES[item.motive]??item.motive)} · ${item.mode==='light'?'senza impegni':`costo: ${esc(item.cost)}`}</small></div></div>`).join('')}${obligations.slice(-3).reverse().map(item=>`<div class="campaign-log-row"><time>G${item.since}</time><div><strong>${esc(item.text)}</strong><small>da onorare dopo il voto</small></div></div>`).join('')}</section>`);
  const runoff=summary.runoff;
  if(runoff) {
    const finalists=campaign.runoffCandidateIds??[];
    blocks.push(`<section class="campaign-block campaign-runoff"><div class="campaign-section-head"><div><span class="campaign-kicker">BALLOTTAGGIO</span><h3>I voti degli esclusi</h3></div><small>${finalists.map(id=>`${esc(nameOf(campaign,parties,id))} ${pct(runoff.projection?.[id]??0)}`).join(' · ')} · proiezione con le scelte fatte finora</small></div>${(runoff.transfers??[]).map(row=>`<div class="campaign-log-row"><time>${pct(row.share)}</time><div><strong>${esc(nameOf(campaign,parties,row.candidateId))}${row.pact?' · apparentato':row.backs?` · sostiene ${esc(nameOf(campaign,parties,row.backs))}`:' · libertà di voto'}</strong><small>${Object.entries(row.rates).map(([id,rate])=>`${Math.round(rate*100)}% a ${esc(nameOf(campaign,parties,id))}`).join(' · ')} · ${Math.round(row.abstain*100)}% non vota</small></div></div>`).join('')}<p class="campaign-footnote">Gli esclusi indicano per chi votare, ma gli elettori li seguono solo in parte e molti restano a casa. Accordi, appelli, la strategia e la mobilitazione cambiano i numeri.</p></section>`);
  }
  return blocks.join('');
}

// The bar under every figure of the three measures, drawn the same way: a share of the votes fills from the left (0–100%); the change since the start is centred on zero (±5 points fill each half).
function metricBar(value,delta=false) {
  if (value===null||value===undefined||!Number.isFinite(Number(value))) return '<div class="metric-bar is-empty" aria-hidden="true"><i style="width:0%"></i></div>';
  if (delta) { const v=Math.max(-5,Math.min(5,Number(value))); const width=Math.abs(v)/5*50; return `<div class="metric-bar is-delta ${v<0?'is-down':'is-up'}" aria-hidden="true"><i style="width:${width}%;${v<0?`right:50%`:`left:50%`}"></i></div>`; }
  return `<div class="metric-bar" aria-hidden="true"><i style="width:${Math.max(1,Math.min(100,Number(value)))}%"></i></div>`;
}
function renderActive(campaign,parties,logoFor,picks={}) {
  const summary=campaignSummary(campaign);
  const player=campaign.candidates.find(item=>item.isPlayer);
  const party=parties.find(item=>item.id===campaign.partyId);
  const days=summary.daysRemaining;
  const weeks=Math.floor(days/7), remainder=days%7;
  const nomination=campaign.nomination.status==='pending'?`Sostegno interno: ${campaign.nomination.internalSupport}/10 · candidatura da confermare entro ${campaign.nomination.deadlineDay} giorni.`:campaign.nomination.status==='excluded'?'Escluso dalla candidatura del partito.':'Candidatura confermata.';
  const resources=[['Fondi simulati',`€${number(player.resources.money)}`],['Volontari',`${number(player.resources.volunteers)} · qualità ${number(summary.crew.quality)}`],['Fatica delle squadre',`${number(summary.crew.average)}%${summary.crew.tired?' · stanche':''}`],['Organizzazione',`${number(player.resources.organization)}/100`],['Visibilità',`${number(campaign.resources.visibility)}/100`],['Capitale politico',number(player.resources.politicalCapital)],...(summary.turnout?[['Affluenza prevista',pct(summary.turnout.value)]]:[])];
  const metrics=campaignMetrics(campaign);
  const historyPoints=(metrics.history.length?metrics.history:campaign.consensusHistory).map(item=>Number(item.value));
  const historyMin=Math.min(...historyPoints,0); const historyMax=Math.max(...historyPoints,10);
  const spark=historyPoints.map((value,index)=>`${historyPoints.length<=1?4:index*92/(historyPoints.length-1)+4},${27-(value-historyMin)/(historyMax-historyMin||1)*21}`).join(' ');
  const latestPoll=campaign.polls?.at(-1);
  const playerPoll=latestPoll?.results?.find(item=>item.candidateId===campaign.playerCandidateId);
  const areas=summary.territories.map(area=>`<div class="campaign-area-row"><div><strong>${esc(area.name)}</strong><small>${weightPercent(area.weight)}% del peso · andamento ${area.localTrend>.35?'favorevole':area.localTrend<-.35?'in calo':'stabile'} · ${area.consensus>25?'forte presenza':area.consensus<11?'da recuperare':'area contendibile'}</small></div><strong>${pct(area.consensus)}</strong><div class="campaign-meter"><i style="width:${Math.max(3,area.consensus)}%"></i></div></div>`).join('');
  const rivals=campaign.candidates.filter(item=>!item.isPlayer).map(candidate=>{
    const affiliated=parties.find(item=>item.id===candidate.partyId);
    const support=summary.territories.reduce((sum,area)=>sum+Number(campaign.territories.find(t=>t.id===area.id)?.supportByCandidate[candidate.id]??0)*area.weight,0)/100;
    const img=affiliated&&logoFor(affiliated)?`<img src="${esc(logoFor(affiliated))}" alt="${esc(affiliated.logoAlt??`Logo ${partyName(affiliated)}`)}">`:'';
    const affiliation=realIdentity(candidate)??(affiliated?partyName(affiliated):'Indipendente simulato');
    const initials=candidate.realReference?candidate.realReference.fullName.split(/\s+/).map(word=>word[0]).join('').slice(0,2):(affiliated?.abbreviation??'S').slice(0,2);
    const realMark=candidate.realReference&&affiliationOf(candidate.realReference.politicianId)?markForPerson(candidate.realReference.politicianId):'';
    const targeted=campaign.strategy?.id==='contrasto'&&campaign.strategy.targetId===candidate.id;
    return `<div class="campaign-rival ${candidate.status==='allied'?'is-allied':''} ${candidate.status==='withdrawn'?'is-withdrawn':''} ${candidate.realReference?'is-real':''} ${targeted?'is-target':''}"><div class="campaign-rival-logo">${realMark||img||esc(initials)}</div><div class="campaign-rival-main"><strong>${candidate.realReference?esc(candidate.realReference.fullName):'Candidatura simulata'}${targeted?' <em>nel mirino</em>':''}</strong><span>${esc(affiliation)}${!candidate.realReference&&affiliated?.abbreviation?` · ${esc(affiliated.abbreviation)}`:''}${candidate.incumbent?' · amministrazione uscente':''}${candidate.recognition?` · ti conosce: rapporto ${esc(candidate.recognition.stance)} (${number(candidate.recognition.met)} ${candidate.recognition.met===1?'incontro':'incontri'})`:''}${candidate.status==='eliminated'?' · escluso al primo turno':''}</span><small>${candidate.realReference?'Persona reale · dati di campagna simulati · ':''}${esc(candidate.lastAction)}</small>${realSourceLink(candidate)}</div><div class="campaign-rival-score"><strong>${pct(support)}</strong><span>${candidate.status==='allied'?'in alleanza':candidate.status==='withdrawn'?'ritirata':`risorse ${number(candidate.resources.money)} €`}</span></div>${affiliated?`<button class="text-link" data-party-profile="${esc(affiliated.id)}">Scheda partito ↗</button>`:''}</div>`;
  }).join('');
  const territoryId=picked(picks.territory,campaign.territories.map(area=>area.id),campaign.candidacy?.territoryId);
  const topicId=picked(picks.topic,DEBATE_TOPICS.map(topic=>topic.id),campaign.strategy?.topicId??campaign.nationalContext.salientTopic);
  const allies=campaign.stage==='ballottaggio'&&player.status==='active'?campaign.candidates.filter(item=>!item.isPlayer&&item.status==='eliminated'):campaign.candidates.filter(item=>!item.isPlayer&&item.status==='active');
  const allyId=picked(picks.ally,allies.map(item=>item.id),allies[0]?.id);
  const territoryOptions=campaign.territories.map(area=>`<option value="${esc(area.id)}" ${area.id===territoryId?'selected':''}>${esc(area.name)}</option>`).join('');
  const debateOptions=DEBATE_TOPICS.map(topic=>`<option value="${topic.id}" ${topic.id===topicId?'selected':''}>${esc(topic.label)} · preparazione ${number(campaign.preparationByTopic[topic.id]??0)}${topic.id===campaign.nationalContext.salientTopic?' · al centro del dibattito':''}</option>`).join('');
  const allyOptions=allies.map(candidate=>{const affiliated=parties.find(item=>item.id===candidate.partyId);return `<option value="${esc(candidate.id)}" ${candidate.id===allyId?'selected':''}>${candidate.realReference?esc(candidate.realReference.fullName):`Candidatura simulata · ${esc(affiliated?partyName(affiliated):'indipendente')}`}</option>`;}).join('');
  const strategy=strategyOf(campaign);
  const list=campaignActivities(campaign);
  const activityGroups=CATEGORY_GROUPS.map(([category,label,icon])=>{
    const rows=list.filter(item=>item.activity.category===category);
    if(!rows.length)return '';
    const available=rows.filter(item=>item.ok).length;
    const body=rows.map(({activity,ok,reason,modifiers,expected})=>{
      const chips=[['Fase',modifiers.phase],['Elezione',modifiers.type],['Strategia',modifiers.strategy],['Ripetizione',modifiers.repetition],['Tema',modifiers.topic],['Clima',modifiers.mood],['Partito',modifiers.party],['Area',modifiers.area],['Squadra',modifiers.crew]].filter(([,value])=>factorLabel(value)).map(([name,value])=>`<i class="${value>1?'up':'down'}">${esc(name)} ${factorLabel(value)}</i>`).join('');
      const risk=Math.round(activity.risk*(strategy.risk??1));
      return `<div class="campaign-activity ${ok?'':'is-blocked'}"><div class="campaign-activity-copy"><strong>${esc(activity.label)}</strong><span>${esc(activity.detail)}</span><small>${activity.days} ${activity.days===1?'giorno':'giorni'} · Rischio ${risk}/100 · ${esc(SCOPE_NAMES[activity.scope]??'Territorio')}${expected?` · effetto atteso <b>+${String(expected).replace('.',',')} punti</b>`:''}</small>${chips?`<span class="campaign-mods">${chips}</span>`:''}</div><div class="campaign-activity-cost">${esc(activityCost(activity))}</div><button class="campaign-action-button" data-campaign-activity="${activity.id}" ${ok?'':'disabled'}>${ok?'Scegli':'Non disponibile'}</button>${reason?`<small class="campaign-activity-reason">${esc(reason)}</small>`:''}</div>`;
    }).join('');
    return `<details class="campaign-activity-group" data-remember="campagna-${category}" ${['territory','media','event'].includes(category)?'open':''}><summary>${glyph(icon,16)}<span>${esc(label)}</span><small>${available} disponibili su ${rows.length}</small></summary>${body}</details>`;
  }).join('');
  const pending=campaign.pendingEvents.map(event=>`<article class="campaign-event-choice"><span class="campaign-kicker">EVENTO · ${esc(formatDate(event.date,{day:'numeric',month:'short'}))}</span><h4>${esc(event.title)}</h4><p>${esc(event.body)}</p><div>${event.choices.map(choice=>`<button class="secondary-button" data-campaign-event="${esc(event.id)}" data-campaign-choice="${esc(choice.id)}">${esc(choice.label)}</button>`).join('')}</div></article>`).join('');
  const history=campaign.history.slice(0,6).map(item=>`<div class="campaign-log-row"><time>G${item.day}</time><div><strong>${esc(item.text)}</strong><small>${esc(formatDate(item.date,{day:'numeric',month:'short'}))} · simulazione</small></div></div>`).join('');
  const activeAlliances=campaign.alliances.filter(item=>item.status==='active').map(alliance=>{const counterpart=campaign.candidates.find(item=>item.id===alliance.partnerCandidateId);const affiliated=parties.find(item=>item.id===counterpart?.partyId);const own=alliance.leaderCandidateId===campaign.playerCandidateId;return `<div class="campaign-alliance-row"><span>↔</span><div><strong>${esc(own?(counterpart?.realReference?.fullName??(affiliated?partyName(affiliated):'Candidatura simulata')):'Accordo fra altre candidature')}</strong><small>${esc(alliance.terms)}${alliance.transfer?` · ${Math.round(alliance.transfer*100)}% dei voti segue l’accordo`:''}</small></div>${own?`<button class="secondary-button" data-campaign-break-alliance="${esc(alliance.id)}">Interrompi</button>`:''}</div>`;}).join('');
  const internalRivals=campaign.internalCandidates.map(item=>`<span>${esc(item.displayName)} · ${number(item.internalSupport)}/10</span>`).join('');
  const nominationPanel=campaign.nomination.status==='pending'?`<div class="campaign-nomination ${campaign.nomination.incumbent?'is-incumbent':''}"><div><strong>${campaign.nomination.incumbent?'Ricandidatura da negoziare':'Candidatura da ottenere'}</strong><span>${esc(nomination)} La competizione interna può cambiare prima della scadenza; superare la soglia rende la candidatura probabile, non certa.</span></div>${internalRivals?`<div class="campaign-internal-rivals"><small>CONCORRENTI INTERNI SIMULATI</small>${internalRivals}</div>`:''}</div>`:`<div class="campaign-nomination is-approved"><strong>${campaign.nomination.status==='excluded'?'Candidatura esclusa':'Candidatura confermata'}</strong><span>${esc(nomination)}${campaign.nomination.decision?.lowerPlace?` In lista al posto ${campaign.candidacy.listPosition}: meno di quanto speravi.`:''}</span></div>`;
  // What the two folded panels say when closed: the strongest and the weakest area; the leading contenders and the player's place. Open, they keep all they had (rows, meters, alliances).
  const byStrength=[...summary.territories].sort((a,b)=>b.consensus-a.consensus);
  const territorySummary=byStrength.length?`Più forte: ${esc(byStrength[0].name)} ${pct(byStrength[0].consensus)}${byStrength.length>1?` · più debole: ${esc(byStrength.at(-1).name)} ${pct(byStrength.at(-1).consensus)}`:''} · ${byStrength.length} ${byStrength.length===1?'area':'aree'}`:'Nessuna area';
  const rivalShares=campaign.candidates.filter(item=>!item.isPlayer&&item.status!=='withdrawn').map(candidate=>({name:candidate.realReference?candidate.realReference.fullName:'Candidatura simulata',support:summary.territories.reduce((sum,area)=>sum+Number(campaign.territories.find(t=>t.id===area.id)?.supportByCandidate[candidate.id]??0)*area.weight,0)/100})).sort((a,b)=>b.support-a.support);
  const opponentSummary=rivalShares.length?`${rivalShares.length} ${rivalShares.length===1?'contendente':'contendenti'} · avanti: ${esc(rivalShares[0].name)} ${pct(rivalShares[0].support)}${summary.playerPosition?` · tu: ${summary.playerPosition}ª posizione`:''}`:'Nessun contendente';
  const crisis=campaign.crisis?`<section class="campaign-crisis" role="status">${glyph('scandal',18)}<div><strong>Polemica in corso: ${esc(campaign.crisis.title)}</strong><span>Ogni settimana costa consenso e reputazione finché non la gestisci (o si spegne da sola dopo tre settimane).</span></div><button class="secondary-button" data-campaign-activity="crisis_response">Gestisci la crisi</button></section>`:'';
  return `<section class="campaign-active-head"><div><span class="campaign-kicker">CAMPAGNA · ${esc(campaign.electionLabel.toUpperCase())}</span><h2>${esc(player.displayName)}</h2><p>${esc(roleLabels[campaign.candidacy.role]??campaign.candidacy.role)} · ${esc(party?partyName(party):'Indipendente')} · ${esc(campaign.territories[0]?.name??'Italia')}</p></div><div class="campaign-countdown"><small>AL VOTO</small><strong>${days}<span>giorni</span></strong><time>${esc(formatDate(campaign.electionDate))}</time></div></section>
  ${phaseStrip(campaign,summary)}
  <section class="campaign-goal-line"><div><small>OBIETTIVO</small><strong>${esc(CAMPAIGN_OBJECTIVES[campaign.objective]?.label??'Costruire una base')}</strong></div><div><small>${metrics.stage==='ballottaggio'?'PROIEZIONE DEL BALLOTTAGGIO':'CONSENSO TERRITORIALE'}</small><strong>${metrics.stage==='ballottaggio'&&metrics.runoffProjection&&!metrics.runoffProjection.finalist?'fuori':pct(metrics.stage==='ballottaggio'&&metrics.runoffProjection?metrics.runoffProjection.share:metrics.territorialConsensus.value)} <span>${metrics.stage==='ballottaggio'?(metrics.runoffProjection&&!metrics.runoffProjection.finalist?'non sei tra i finalisti':'testa a testa con l’altro finalista'):summary.playerPosition?`${summary.playerPosition}ª posizione tra tutte le candidature`:'quota tra tutte le candidature'}</span></strong></div><div><small>CANDIDATURA</small><strong>${campaign.nomination.status==='approved'?'Confermata':campaign.nomination.status==='excluded'?'Esclusa':'Da conquistare'}</strong></div><div><small>PROSSIMA FASE</small><strong>${campaign.stage==='ballottaggio'?'Ballottaggio':`Settimana ${weeks+1}${remainder?` · ${remainder} gg`:''}`}</strong></div></section>
  ${crisis}
  ${pending?`<section class="campaign-event-list">${pending}</section>`:''}
  ${nominationPanel}
  ${strategyPanel(campaign,picks)}
  <section class="campaign-resource-line" aria-label="Risorse della campagna">${resources.map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</section>
  <section class="campaign-consensus-trend campaign-metrics" aria-label="Le percentuali della campagna e che cosa misurano">
    <div class="campaign-metric" data-metric="consenso-territoriale"><small>CONSENSO TERRITORIALE</small><strong>${pct(metrics.territorialConsensus.value)}</strong>${metricBar(metrics.territorialConsensus.value)}<span>${esc(metrics.territorialConsensus.scope)}.${metrics.stage==='ballottaggio'?' Resta la misura del primo turno: al ballottaggio conta la proiezione.':''}</span></div>
    <div class="campaign-metric" data-metric="sondaggio"><small>${esc((metrics.poll?.label??`SONDAGGIO DI CAMPAGNA · ${metrics.stage==='ballottaggio'?'BALLOTTAGGIO':'PRIMO TURNO'}`).toUpperCase())}</small><strong>${metrics.poll?pct(metrics.poll.share):'—'}</strong>${metricBar(metrics.poll?metrics.poll.share:null)}<span>${metrics.poll?`${metrics.poll.margin!==null?`margine ±${metrics.poll.margin.toFixed(1).replace('.',',')} punti · `:''}${metrics.poll.sample?`${number(metrics.poll.sample)} interviste · `:''}${esc(metrics.poll.institute??'media degli istituti')}${metrics.poll.date?` · ${esc(formatDate(metrics.poll.date))}`:''}`:'Nessun sondaggio per questa fase.'}</span></div>
    ${metrics.stage==='ballottaggio'?`<div class="campaign-metric" data-metric="proiezione-ballottaggio"><small>PROIEZIONE DEL BALLOTTAGGIO</small><strong>${metrics.runoffProjection?.finalist?pct(metrics.runoffProjection.share):'fuori'}</strong>${metricBar(metrics.runoffProjection?.finalist?metrics.runoffProjection.share:null)}<span>${esc(metrics.runoffProjection?.scope??'')}${campaign.firstRoundResult?` · al primo turno hai preso ${pct(campaign.firstRoundResult.playerShare)}`:''}</span></div>`:''}
    <div class="campaign-metric" data-metric="andamento"><small>ANDAMENTO${metrics.stage==='ballottaggio'?' NEL BALLOTTAGGIO':' NEL PRIMO TURNO'}</small><strong>${metrics.variation===null?'—':`${metrics.variation>=0?'+':''}${metrics.variation.toFixed(1).replace('.',',')} punti`}</strong>${metricBar(metrics.variation,true)}<span>${metrics.variation===null?'scenario appena avviato':`dall’inizio ${metrics.stage==='ballottaggio'?'del ballottaggio':'della campagna'}`}${summary.expectation!==null&&metrics.stage!=='ballottaggio'?` · attesa iniziale ${pct(summary.expectation)}`:''}</span></div>
    <svg viewBox="0 0 100 30" preserveAspectRatio="none" aria-label="Andamento della fase in corso"><polyline points="${spark}" /></svg>
  </section>
  <div class="campaign-columns"><details class="campaign-block campaign-territories campaign-fold" data-remember="camp-geografia"><summary class="campaign-section-head"><div><span class="campaign-kicker">GEOGRAFIA DEL VOTO</span><h3>Dove sei forte</h3></div><small class="campaign-fold-summary">${territorySummary}</small></summary><div class="campaign-fold-body"><p class="campaign-note-small">Clima nazionale simulato ${number(campaign.nationalContext.moodIndex)}/100 · ${campaign.nationalContext.macroTrend>0?'tendenza favorevole':campaign.nationalContext.macroTrend<0?'contesto in calo':'contesto stabile'} · tema: ${esc(DEBATE_TOPICS.find(topic=>topic.id===campaign.nationalContext.salientTopic)?.label??'scenario politico')}</p>${areas}<p class="campaign-footnote">Le percentuali territoriali sono la base di consenso simulata; i sondaggi settimanali stimano la stessa base e possono differire per errore campionario.</p></div></details>
  <details class="campaign-block campaign-opponents campaign-fold" data-remember="camp-contendenti"><summary class="campaign-section-head"><div><span class="campaign-kicker">CONTENDENTI</span><h3>Le altre campagne</h3></div><small class="campaign-fold-summary">${opponentSummary}</small></summary><div class="campaign-fold-body"><p class="campaign-note-small">${number(campaign.aiTurns)} turni di campagna simulati</p>${rivals||'<p>Nessuna candidatura simulata disponibile.</p>'}${activeAlliances?`<div class="campaign-alliance-list"><span class="campaign-kicker">ACCORDI ATTIVI</span>${activeAlliances}</div>`:''}<div class="campaign-opponent-note">Le candidature avversarie sono simulate. Se mostrano un partito reale, il legame è un riferimento d’identità; le percentuali e le strategie sono generate dal gioco.</div></div></details></div>
  <section class="campaign-block campaign-activities"><div class="campaign-section-head"><div><span class="campaign-kicker">DECIDI COME IMPIEGARE LE RISORSE</span><h3>Attività di campagna</h3></div><small>Giorni, denaro, organizzazione e rischio sono limitati; l’effetto dipende da fase, elezione, strategia e ripetizione</small></div><div class="campaign-activity-controls"><label>Territorio<select data-campaign-territory>${territoryOptions}</select></label><label>Tema<select data-campaign-topic>${debateOptions}</select></label>${allyOptions?`<label>${campaign.stage==='ballottaggio'?(player.status==='active'?'Candidato escluso (apparentamento)':'Finalista da sostenere'):'Avversario o possibile alleato'}<select data-campaign-ally>${allyOptions}</select></label>`:''}</div><div class="campaign-activity-groups">${activityGroups}</div></section>
  ${campaign.events.length?`<section class="campaign-block campaign-events-resolved"><div class="campaign-section-head"><div><span class="campaign-kicker">CRONACA DELLA CAMPAGNA</span><h3>Eventi già affrontati</h3></div></div>${campaign.events.slice(0,4).map(event=>`<div class="campaign-log-row"><time>${esc(formatDate(event.date,{day:'numeric',month:'short'}))}</time><div><strong>${esc(event.title)}</strong><small>${esc(event.choiceLabel)}${event.outcome?` · ${esc(event.outcome)}`:''} · dato simulato</small></div></div>`).join('')}</section>`:''}
  <section class="campaign-block campaign-history"><div class="campaign-section-head"><div><span class="campaign-kicker">TRACCIA DELLE DECISIONI</span><h3>Ultime mosse</h3></div><small>La partita viene salvata dopo ogni scelta</small></div>${history}</section>
  <footer class="campaign-rules-note"><span>Modello: ${esc(campaign.model)} · ${esc(sourceText('simulation'))}</span><span>Meccaniche elettorali semplificate per il gioco; <a href="${esc(ELECTION_MODELS[campaign.electionType]?.referenceUrl??'#')}" target="_blank" rel="noopener noreferrer">fonte istituzionale di riferimento ↗</a>. Non sostituiscono la normativa o un calcolo ufficiale.</span></footer>`;
}

function renderResult(campaign,parties,logoFor,state={}) {
  const result=campaign.result;
  const report=state.career?.lastElectionReport?.campaignId===campaign.id?state.career.lastElectionReport:null;
  return `<section class="campaign-result-head"><span class="campaign-kicker">SCRUTINIO CONCLUSO · RISULTATO SIMULATO</span><h2>${esc(result?.outcome?.label??(result?.objectiveMet?'Obiettivo raggiunto.':'La corsa è finita.'))}</h2><p>${esc(resultDescription(campaign,result))}${parliamentOutcome(campaign,state)?` ${esc(parliamentOutcome(campaign,state))}`:''}</p></section>
  ${report?renderElectionReport(report,{place:mandatePlace(state,report)}):`<p class="campaign-real-note">Percentuale ${pct(result?.playerShare??0)} · seggi ${number(result?.playerSeats??0)} · mandato ${result?.personalMandate?'sì':'no'}.</p>`}
  <section class="campaign-block campaign-history"><div class="campaign-section-head"><div><span class="campaign-kicker">STORICO</span><h3>Chiusura della campagna</h3></div><time>${esc(formatDate(campaign.closedAt))}</time></div>${campaign.history.slice(0,8).map(item=>`<div class="campaign-log-row"><time>G${item.day}</time><div><strong>${esc(item.text)}</strong><small>${esc(formatDate(item.date,{day:'numeric',month:'short'}))} · simulazione</small></div></div>`).join('')}</section><div class="campaign-result-actions"><span>Il risultato e l’impatto sulla carriera sono salvati in questo browser.</span>${(place=>place?`<button class="secondary-button" data-nav="${place.nav}"${place.scroll?` data-scroll="${place.scroll}"`:''}>${esc(place.label)}</button>`:'')(mandatePlace(state,report??{electionType:campaign.electionType,personalMandate:result?.personalMandate}))}<button class="primary-button" data-action="campaign-new">Prepara una nuova elezione</button></div><footer class="campaign-rules-note"><span>Modello: ${esc(result?.model??campaign.model)} · ${esc(sourceText('simulation'))}</span><span>Le cifre sono prodotte dal motore di gioco, non sono risultati reali; soglia UE del 4% da fonte verificata. <a href="${esc(ELECTION_MODELS[campaign.electionType]?.referenceUrl??'#')}" target="_blank" rel="noopener noreferrer">Riferimento istituzionale ↗</a></span></footer>`;
}

function parliamentOutcome(campaign,state) {
  if(campaign.electionType!=='politiche') return '';
  if(campaign.result?.personalMandate&&state.career?.parliamentContext) return state.career.parliamentContext.groupId?'Il mandato parlamentare prosegue con il tuo gruppo.':'Mandato parlamentare ottenuto: scegli il gruppo nella sezione Parlamento.';
  if(campaign.candidacy.incumbent&&!campaign.result?.personalMandate) return 'Il seggio non è stato confermato: il mandato parlamentare si conclude e le proposte in esame decadono.';
  return '';
}
